plan={'task':'DEV_AUX2607_ROOT_FEASIBILITY','state':'FROZEN_BEFORE_AUDIT','question':'Can a deterministic reserved family-ID pool provide at least 16 unique, exact full-rule/history evaluation roots per rule, disjoint from every potential 4-ply training-family root?','purpose':'Root-sampler feasibility only; no training, model fitting, or outcomes.','rules':rules,'training_family_ids':[990000,990511],'evaluation_candidate_family_ids':[991000,992023],'prefix_plies':4,'minimum_selected_unique_disjoint_roots_per_rule':16,'selection':'For each rule, scan candidate family IDs ascending; accept the first 16 legal, nonterminal, full-4-ply roots whose exact canonical GameSession record is absent from the complete 512-family training set and earlier accepted eval records. No outcome-dependent selection.','rejection_precedence':['PREFIX_TERMINAL_OR_SHORT','TRAIN_EXACT_RECORD_OVERLAP','EVAL_EXACT_RECORD_DUPLICATE','ACCEPT_FIRST_16','VALID_AFTER_TARGET'],'identity':'Complete canonical GameSession record including ruleset_fingerprint and complete action history; no normalization that could hide exact collisions.','shortage':'If any rule yields fewer than 16, stop with INSUFFICIENT_ROOTS; do not expand ranges or relax criteria.','source_pins':pins,'expected_duration_minutes':2,'hard_cap_seconds':120}
